	    public void MapPoco(SubCountry newPoco)
        {   
		    newPoco.Code = this.Code;  
			newPoco.SearchFields = GetSearchFields(this);   
		    newPoco.CountryCode = this.CountryCode;  
		    newPoco.Inactive = this.Inactive;  
		    newPoco.LocalName = this.LocalName;   
        }

		public string GetSearchFields(SubCountry rec)
        {   
           return String.Concat(rec.Code,",",rec.CountryCode,",",rec.Inactive,",",rec.LocalName,",");
        }
   }
